cd /home/dev/garden/bench/results/2026-10-12/m1-ngram/recon && python3 - <<'EOF'
import json
inv = json.load(open("inventory.json"))
for run in inv["runs"]:
    if "mem0" in run["run_id"]:
        print("run:", run["run_id"])
        print("mem0_dbs:", json.dumps(run["mem0_dbs"], indent=1)[:400])
        print("num steps:", len(run["steps"]))
        for sk, s in sorted(run["steps"].items()):
            roles = {}
            for r in s.get("tap_records", []):
                roles[r["role"]] = roles.get(r["role"], 0) + 1
            mem_recs = [r for r in s.get("tap_records", []) if r["role"] == "mem"]
            print(f"  step {sk}: {roles} | mem recs:", json.dumps(mem_recs))
EOF

