#!/usr/bin/env python3
"""Build the M1 n-gram replay set from host-recorded bonsai-garden traffic.

Reads host event JSONL (one per step), the per-run SQLite mem0 stores and the
recorded request logs, then writes:
  bench/.replay/m1/agent.jsonl
  bench/.replay/m1/mem.jsonl
  bench/results/.../m1-ngram/replay_manifest.json

Mem bodies are rebuilt per call (not per step): a tool add uses the add's
new_msgs and the toolResult timestamp cutoff; the auto-capture uses the user
prompt + first assistant text and the capture's assistant message timestamp.
"""
from __future__ import annotations

import argparse
import json
import pathlib
import re
import sqlite3
import statistics
import sys
from datetime import datetime, timezone

ROOT = pathlib.Path(__file__).resolve().parent.parent
RECON = ROOT / "bench" / "results" / "2026-10-12" / "m1-ngram" / "recon"
DB_BASE = RECON / "dbs"
OUT_DIR = ROOT / "bench" / ".replay" / "m1"
MANIFEST = RECON / "replay_manifest.json"
MEM_DEFAULT_DATE = "2026-10-11"


def log(*a):
    print(*a, file=sys.stderr)


def parse_args():
    ap = argparse.ArgumentParser(description=__doc__.strip())
    ap.add_argument("--per-step", type=int, default=5,
                    help="agent turns per chosen step (default 5)")
    ap.add_argument("--agent-max", type=int, default=30,
                    help="max agent requests (default 30)")
    ap.add_argument("--mem-max", type=int, default=12,
                    help="max mem requests (default 12)")
    ap.add_argument("--dry-run", action="store_true",
                    help="report the plan, do not write files")
    return ap.parse_args()


def parse_ts(v):
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str) and v:
        try:
            return datetime.fromisoformat(v.replace("Z", "+00:00")).timestamp()
        except ValueError:
            return None
    return None


def date_from_session(sess_ts):
    ts = parse_ts(sess_ts)
    if ts is not None:
        return datetime.fromtimestamp(ts, tz=timezone.utc).strftime("%Y-%m-%d")
    return MEM_DEFAULT_DATE


# ---------- message -> openai ----------

def block_text(b):
    if isinstance(b, str):
        return b
    if isinstance(b, dict):
        return b.get("text") or b.get("content") or ""
    return ""


def blocks_text(content):
    if not content:
        return ""
    if isinstance(content, str):
        return content
    return "".join(block_text(b) for b in content)


def arg_str(v):
    """Tool arguments as a string: use as-is if already a string, else dump."""
    if isinstance(v, str):
        return v
    return json.dumps(v)


def system_text(m):
    """System content = recorded sections joined by blank line (join inferred)."""
    s = m.get("sections")
    if not s:
        return m.get("content") or "", False
    return "\n\n".join([t for t in s.values() if t]), True


def tool_list(sysmsg):
    out = []
    for t in (sysmsg or {}).get("toolsAdded") or []:
        name = t.get("name")
        if not name:
            continue
        fn = {k: t[k] for k in ("name", "description", "parameters") if k in t}
        out.append({"type": "function", "function": fn})
    return out


def to_openai(m):
    role = m.get("role")
    if role == "system":
        return {"role": "system", "content": system_text(m)}
    if role == "user":
        return {"role": "user", "content": blocks_text(m.get("content"))}
    if role == "custom":
        # mem0 recall: surface as a user-visible message
        return {"role": "user", "content": blocks_text(m.get("content"))}
    if role == "toolResult":
        return {"role": "tool",
                "content": blocks_text(m.get("content")),
                "tool_call_id": m.get("toolCallId")}
    if role == "assistant":
        content = m.get("content") or []
        txt = block_text({"text": blocks_text(content)})
        calls = [
            {"id": c["id"], "type": "function",
             "function": {"name": c["name"],
                          "arguments": arg_str(c.get("arguments"))}}
            for b in content
            if isinstance(b, dict) and b.get("type") == "toolCall" and b.get("name")
        ]
        out = {"role": "assistant", "content": txt}
        if calls:
            out["tool_calls"] = calls
        return out
    return {"role": role or "user", "content": blocks_text(m.get("content"))}


# ---------- events / steps ----------

def read_events(path):
    session_ts = None
    msgs = None
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                e = json.loads(line)
            except ValueError:
                continue
            t = e.get("type")
            if t == "session":
                session_ts = e.get("timestamp")
            elif t == "agent_end":
                msgs = e.get("messages")
    return session_ts, msgs


def load_steps():
    inv = json.loads((RECON / "inventory.json").read_text(encoding="utf-8"))
    steps = []
    for run in inv["runs"]:
        arm = run["arm"]
        base = RECON / "dbs" / run["id"]
        for si, step in enumerate(run.get("steps", [])):
            ev = step.get("events")
            if not ev:
                continue
            session_ts, msgs = read_events(base / ev)
            n_turns = len([m for m in msgs or [] if m.get("role") == "assistant"])
            steps.append({
                "id": f"{run['id']}/{si}",
                "arm": arm,
                "run_dir": str(base),
                "n_turns": n_turns,
                "sess_ts": session_ts,
                "msgs": msgs or [],
            })
    return steps


def step_score(msgs):
    """Prefer steps with file reads, edits and test output."""
    read = edit = tested = 0
    for m in msgs or []:
        if m.get("role") != "toolResult":
            continue
        name = m.get("toolName")
        if name == "read":
            read += 1
        elif name in ("edit", "write"):
            edit += 1
        elif name == "bash":
            content = str(m.get("content") or "")
            if "test_" in content or "pytest" in content:
                tested += 1
    return read + edit + tested


def pick_agent_steps(steps, per_step, agent_max):
    chosen = []
    for arm in ("baseline", "mem0"):
        cand = [s for s in steps if s["arm"] == arm and s.get("n_turns", 0) >= per_step]
        cand.sort(key=lambda s: (-step_score(s["msgs"]), s["id"]))
        n = max(1, agent_max // per_step // 2)
        chosen += cand[:n]
    return chosen


# ---------- mem0 DB helpers ----------

def existing_memories(con, cols, cutoff, limit=10):
    """Existing memories (mem0 order: last k, ids 0..). Excludes ids whose latest
    action is DELETE. Cutoff (if set) keeps only entries created before the call."""
    tcol = next((c for c in ("new_memory", "new_value", "text", "memory") if c in cols), None)
    ecol = next((c for c in ("action", "event") if c in cols), None)
    if not tcol:
        return [], False
    rows = [dict(r) for r in con.execute("SELECT * FROM memory_history ORDER BY rowid")]
    latest_action = {}
    ordered_ids = []
    latest_text = {}
    filtered = False
    for r in rows:
        mid = str(r.get("memory_id") or r.get("id"))
        rowid = r.get("rowid", 0)
        action = str(r.get(ecol, "")).upper() if ecol else None
        if ecol:
            cur = latest_action.get(mid)
            if cur is None or rowid > cur[0]:
                latest_action[mid] = (rowid, action)
        if ecol and action not in ("ADD", "UPDATE"):
            continue
        ts = parse_ts(r.get("created_at")) if cutoff is not None else None
        if ts is not None:
            filtered = True
            if ts >= cutoff:
                continue
        val = r.get(tcol)
        if val:
            if mid not in latest_text:
                ordered_ids.append(mid)
            latest_text[mid] = val
    kept = [mid for mid in ordered_ids
            if not (mid in latest_action and latest_action[mid][1] in ("DELETE",)) ]
    texts = [latest_text[mid] for mid in kept][-limit:]
    return [{"id": str(i), "text": t} for i, t in enumerate(texts)], filtered


def last_k(con, cols, cutoff, k=10):
    """Last k messages as 'role: content', before the per-call cutoff (if set)."""
    if not {"role", "content"} <= set(cols):
        return []
    rows = [dict(r) for r in con.execute("SELECT * FROM messages ORDER BY rowid")]
    out = []
    for r in rows:
        if cutoff is not None and "created_at" in cols:
            ts = parse_ts(r.get("created_at"))
            if ts is not None and ts >= cutoff:
                continue
        out.append(f"{r['role']}: {r['content']}")
    return out[-k:]


# ---------- mem events (per call, not per step) ----------

def tool_results_index(msgs):
    idx = {}
    for m in msgs:
        if m.get("role") == "toolResult":
            idx[m.get("toolCallId")] = m.get("timestamp")
    return idx


def mem0_adds(msgs):
    """(content, toolCallId) for each mem0_memory add toolCall, in message order."""
    out = []
    for m in msgs:
        if m.get("role") != "assistant":
            continue
        for b in m.get("content") or []:
            if not (isinstance(b, dict) and b.get("type") == "toolCall"
                    and b.get("name") == "mem0_memory"):
                continue
            args = b.get("arguments")
            if isinstance(args, str):
                try:
                    args = json.loads(args)
                except ValueError:
                    args = {}
            if isinstance(args, dict) and args.get("action") == "add":
                out.append((args.get("content") or "", b.get("id")))
    return out


def first_assistant_text(msgs):
    for m in msgs:
        if m.get("role") == "assistant":
            txt = blocks_text(m.get("content") or [])
            if txt.strip():
                return m.get("timestamp"), txt
    return None, ""


def first_user_text(msgs):
    for m in msgs:
        if m.get("role") == "user":
            return blocks_text(m.get("content") or [])
    return ""


def build_mem_events(msgs):
    """Extraction events in order: tool adds (message order) then the auto-capture."""
    trs = tool_results_index(msgs)
    events = []
    for content, tcid in mem0_adds(msgs):
        events.append({
            "kind": "tool_add",
            "new_msgs": "user: " + (content or ""),
            "cutoff": parse_ts(trs.get(tcid)),
        })
    asst_ts, asst_text = first_assistant_text(msgs)
    events.append({
        "kind": "capture",
        "new_msgs": f"user: {first_user_text(msgs)}\nassistant: {asst_text}",
        "cutoff": parse_ts(asst_ts),
    })
    return events


def mem_user_prompt(existing, lastk, new_msgs, date):
    """Rebuild the mem0 user prompt (generateAdditiveExtractionPrompt windows)."""
    sections = [
        "## Summary\n",
        "## Last k Messages\n" + "\n".join(lastk),
        "## Recently Extracted Memories\n[]",
        "## Existing Memories\n" + json.dumps(existing),
        "## New Messages\n" + new_msgs,
        "## Observation Date\n" + date,
        "## Current Date\n" + date,
        "# Output:",
    ]
    return "\n\n".join(sections)


def load_additive(path):
    """ADDITIVE_EXTRACTION_PROMPT, with the \uXXXX escapes decoded.

    The template literal is opened by 'var ADDITIVE_EXTRACTION_PROMPT = `' and
    closed by the next backtick on its own line (line 486)."""
    txt = path.read_text(encoding="utf-8")
    open_pat = "var ADDITIVE_EXTRACTION_PROMPT = `"
    a = txt.index(open_pat) + len(open_pat)
    b = txt.index("`", a)  # the next backtick closes the template
    raw = txt[a:b]
    return re.sub(r"\\u([0-9a-fA-F]{4})",
                  lambda m: chr(int(m.group(1), 16)), raw)


def add_meta(r, step):
    r = dict(r)
    r["meta"] = {
        "role": r["role"],
        "run": step["run_id"],
        "step": step["step_id"],
        "ordinal": r.get("ordinal"),
        "k": r.get("k"),
    }
    if "kind" in r:
        r["meta"]["kind"] = r["kind"]
    return r


def build_agent_bodies(steps):
    by_id = {}
    for step in steps:
        for r in step["recs"]["agent"]:
            by_id[r["id"]] = step
    bodies = []
    for s in steps:
        msgs = s["msgs"]
        asst_idx = [i for i, m in enumerate(msgs) if m.get("role") == "assistant"]
        sysm = msgs[0] if msgs and msgs[0].get("role") == "system" else None
        sp, exact = system_text(sysm)
        tl = tool_list(sysm)
        for t, rec in enumerate(s["recs"]["agent"]):
            if t >= len(asst_idx):
                continue
            hist = [to_openai(m) for m in msgs[: asst_idx[t]]]
            bodies.append({
                "id": rec["id"],
                "role": "agent",
                "n_messages": rec["n_messages"],
                "system_prompt_exact": exact,
                "prompt_tokens": rec["prompt_tokens"],
                "model": rec["model"],
                "history": hist,
                "tools": tl,
                "metadata": add_meta(rec, s),
            })
    return bodies


def build_mem_bodies(steps, additive):
    bodies = []
    for s in steps:
        if s["arm"] != "mem0":
            continue
        run_dir = s["run_dir"]
        date = date_from_session(s["sess_ts"])
        try:
            con = sqlite3.connect(str(run_dir / "mem0_dbs" / "mem0-history.db"))
            with con:
                cols_h = {c[0] for c in con.execute("PRAGMA table_info(memory_history)").fetchall()}
                cols_m = {c[0] for c in con.execute("PRAGMA table_info(messages)").fetchall()}
                con.close()
        except sqlite3.Error as e:
            log(f"  db error {run_dir}: {e}")
            continue
        with sqlite3.connect(str(run_dir / "mem0_dbs" / "mem0-history.db")) as con:
            events = build_mem_events(s["msgs"])
            if len(events) != len(s["recs"]["mem"]):
                log(f"  {s['id']}: {len(events)} mem events vs "
                    f"{len(s['recs']['mem'])} tap records (mismatch)")
            for i, rec in enumerate(s["recs"]["mem"]):
                if i >= len(events):
                    break
                ev = events[i]
                ex, filtered = existing_memories(con, cols_h, ev["cutoff"])
                lk = last_k(con, cols_m, ev["cutoff"])
                up = mem_user_prompt(ex, lk, ev["new_msgs"], date)
                body = {
                    "messages": [
                        {"role": "system", "content": additive},
                        {"role": "user", "content": up},
                    ],
                    "chat_template_kwargs": {"enable_thinking": False},
                    "response_format": {"type": "json_object"},
                }
                body_meta = add_meta(rec, s)
                body_meta["kind"] = ev["kind"]
                body_meta["cutoff_ms"] = ev["cutoff"]
                body_meta["existing_n"] = len(ex)
                body_meta["lastk_n"] = len(lk)
                body = {
                    "id": rec["id"],
                    "role": "mem",
                    "n_messages": rec["n_messages"],
                    "system_prompt_exact": False,
                    "prompt_tokens": rec["prompt_tokens"],
                    "model": rec["model"],
                    "history": body,
                    "metadata": body_meta,
                }
                bodies.append(body)
    return bodies


def main():
    args = parse_args()
    log(f"per_step={args.per_step} agent_max={args.agent_max} mem_max={args.mem_max}")
    log(f"recon={RECON}")
    log(f"output={OUT_DIR}")

    # load steps
    steps = load_steps()
    log(f"steps: {len(steps)} total ({sum(1 for s in steps if s['arm']=='mem0')} mem0)")

    additive = load_additive(RECON / "mem0_additive_extraction_prompt.txt")
    log(f"additive prompt chars: {len(additive)}")

    # agent selection
    agent_steps = pick_agent_steps(steps, args.per_step, args.agent_max)
    log(f"agent steps: {[s['id'] for s in agent_steps]}")

    # agent bodies
    agent_bodies = build_agent_bodies(agent_steps)
    log(f"agent requests: {len(agent_bodies)} "
        f"(steps {len({s['id'] for s in agent_steps})})")

    # mem bodies
    mem_bodies = build_mem_bodies(steps, additive)
    log(f"mem requests: {len(mem_bodies)}")

    if args.dry_run:
        log("dry run: not writing files")
        return

    # write
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    with open(OUT_DIR / "agent.jsonl", "w", encoding="utf-8") as f:
        for b in agent_bodies:
            f.write(json.dumps(b, ensure_ascii=False) + "\n")
    with open(OUT_DIR / "mem.jsonl", "w", encoding="utf-8") as f:
        for b in mem_bodies:
            f.write(json.dumps(b, ensure_ascii=False) + "\n")

    # manifest
    manifest = build_manifest(agent_bodies, mem_bodies, additive)
    MANIFEST.parent.mkdir(parents=True, exist_ok=True)
    MANIFEST.write_text(json.dumps(manifest, indent=2, ensure_ascii=False))
    log(f"manifest: {MANIFEST}")
    log(f"done: {len(agent_bodies)} agent, {len(mem_bodies)} mem")


def build_manifest(agent_bodies, mem_bodies, additive):
    manifest = {}

    # per-request stats
    per_request = []
    for b in agent_bodies + mem_bodies:
        hist = b["history"]
        # prompt text = system + user parts
        prompt_text = ""
        for m in hist:
            if m.get("role") in ("system", "user", "tool"):
                prompt_text += str(m.get("content", "")) + "\n"
        est_tokens_chars4 = len(prompt_text) / 4.0
        rec_tokens = b.get("prompt_tokens")
        per_request.append({
            "id": b["id"],
            "role": b["role"],
            "n_messages": b["n_messages"],
            "prompt_chars": len(prompt_text),
            "est_tokens_chars4": est_tokens_chars4,
            "recorded_prompt_tokens": rec_tokens,
            "est_over_recorded": (est_tokens_chars4 / rec_tokens
                                  if rec_tokens else None),
        })

    # totals per role
    totals = {}
    for role in ("agent", "mem"):
        rs = [p for p in per_request if p["role"] == role]
        ratios = [p["est_over_recorded"] for p in rs if p["est_over_recorded"] is not None]
        distinct = len({p["id"].rsplit("/", 1)[0] for p in rs})
        totals[role] = {
            "requests": len(rs),
            "distinct_steps": distinct,
            "prompt_chars": sum(p["prompt_chars"] for p in rs),
            "recorded_prompt_tokens": sum(p["recorded_prompt_tokens"] for p in rs),
            "median_ratio": statistics.median(ratios) if ratios else None,
        }

    manifest["per_request"] = per_request
    manifest["totals"] = totals

    # system prompt exact: only 2-message first requests can support the join
    agent_first = [p["est_over_recorded"]
                   for p in per_request if p["role"] == "agent" and p["n_messages"] <= 3]
    first_ratios_ok = (not agent_first) or all(0.75 <= r <= 1.33 for r in agent_first)
    manifest["system_prompt_exact"] = first_ratios_ok
    manifest["system_prompt_note"] = (
        "agent system prompt = recorded sections joined by '\\n\\n' "
        "(join inferred; getSystemMessageText not in source dump)"
    )
    manifest["agent_first_ratios"] = agent_first
    manifest["n_messages_mismatches"] = (
        len([p for p in per_request
             if p["role"] == "agent" and p["n_messages"] is not None])
    )
    manifest["outliers"] = (
        [p["id"] for p in per_request
         if p["est_over_recorded"] is not None
         and (p["est_over_recorded"] < 0.75 or p["est_over_recorded"] > 1.33)]
    )
    return manifest


if __name__ == "__main__":
    main()

